
export const getUserSource = () => {
  const serviceMapping = window.sessionStorage.getItem('service_list') ? JSON.parse(window.sessionStorage.getItem('service_list')) : []
  if (serviceMapping && serviceMapping.length) {
    const MAX_AGENCY_SOURCES = 1
    const agencySource = serviceMapping.filter((item) => item.includes('agency'))

    if (!agencySource || agencySource.length === 0) {
      return false
    }

    // For cases where a customer is an agent as well as an agency customer,
    // There are two mappings available as agency_customer, agency_agent.
    // For such cases, `agency_agent` will be dominant.
    if (agencySource && agencySource.length > MAX_AGENCY_SOURCES) {
      return 'agency_agent'
    }
    return agencySource[0]
  }
}

export const policyDetailMapping = (agentDetails) => {
  const detailsData = {}
  detailsData['Name'] = agentDetails.request?.customer_data?.name || agentDetails?.name
  detailsData['ApplicationNo'] = agentDetails.app_no
  detailsData['Category'] = {
    'Code': agentDetails?.provider_package?.package?.product?.code,
    'Name': agentDetails?.provider_package?.package?.product?.name
  }
  detailsData['ExpiresAtObject'] = {
    'Time': agentDetails?.coverage_period?.end,
    'Valid': agentDetails?.coverage_period?.status === 'ACTIVE',
    'CustomStatus': agentDetails?.coverage_period?.custom_status
  }
  detailsData['Payments'] = [{
    'CoverageEndDate': agentDetails.coverage_period?.end,
    'CoverageStartDate': agentDetails.coverage_period?.start,
    'Amount': (() => {
      try {
        const grossPremium = agentDetails.payment_detail?.gross_premium
        if (!grossPremium) return grossPremium

        return Number(grossPremium.split('.')[0].split(',').join(''))
      } catch (error) {
        return agentDetails.payment_detail?.gross_premium
      }
    })()
  }]

  detailsData['InternalID'] = agentDetails?.reference_id
  detailsData['InsurancePolicyNo'] = agentDetails?.insurance_policy_no
  detailsData['CreatedAt'] = agentDetails?.created_at || agentDetails?.created_at
  detailsData['Benefits'] = agentDetails?.request?.package_detail_response?.benefit?.data.map((item) => item.title)
  detailsData['PartnerLogoSquare'] = agentDetails?.provider_package?.provider?.logo_url
  detailsData['DocumentURL'] = agentDetails?.document_url
  detailsData['ProductKey'] = agentDetails?.provider_package?.package?.product?.code
  detailsData['PackageCode'] = agentDetails?.provider_package?.package?.code
  detailsData['PackageCodeSlug'] = agentDetails?.provider_package?.package?.code
  detailsData['InsuranceProvider'] = agentDetails?.provider_package?.provider?.code
  detailsData['PolicyType'] = agentDetails?.additional_detail.policy_type

  if (agentDetails?.provider_package?.provider?.code === 'offline') {
    const policy = agentDetails.request
    const packageCode = typeof policy?.package === 'string' ? policy?.package : policy?.package_code

    detailsData['PackageCodeSlug'] = packageCode
    detailsData['ProductKey'] = policy?.product_key || policy?.product_code
    detailsData['InsuranceProvider'] = policy?.provider_code
    detailsData['PackageCode'] = packageCode
  }
  return detailsData
}

export const belongsToAnotherVertical = () => {
  const { services: serviceMapping = [] } = window.sessionStorage.getItem('service_list') || {}

  if (!serviceMapping || serviceMapping.length === 0) {
    return false
  }
  // Belongs to more than 1 vertical
  if (serviceMapping.length > 1) {
    return true
  }

  return false
}
