import _ from 'lodash'

export const getPolicyId = (policy, isTrucate) => {
  // return the application number if policyId is empty or - is coming
  const { InsurancePolicyNo, ApplicationNo } = policy
  const policyId = InsurancePolicyNo === '' || InsurancePolicyNo === '-' ? ApplicationNo : InsurancePolicyNo
  return isTrucate ? _.truncate(policyId, { length: '15' }) : policyId
}

export const getPolicyStartDate = (data = []) => {
  // this function returns the minmum date timestamp from the array
  // if array length is greater than 1 else return first object
  const dataLength = _.size(data)
  if (!dataLength) {
    return null
  }
  let minDate = Date.parse(_.get(data, '[0].CoverageStartDate', ''))
  // most of time it's single value
  if (dataLength > 1) {
    for (let index; index < dataLength; index++) {
      const dateTimeStamp = Date.parse(_.get(data, `[${index}].CoverageStartDate`, '-'))
      if (dateTimeStamp && (dateTimeStamp < minDate)) {
        minDate = dateTimeStamp
      }
    }
  }
  return minDate
}
