import moment from 'moment'
import NumberFormat from 'react-number-format'
import IntlMessages from '../../../../components/utility/intlMessages'
import { getPolicyId } from '../../../../helpers/policyUtils'
import { calculateDuration, getCoverageMeta } from '../policyDetailHelpers'
import {
  CALENDAR,
  CART,
  CLOCK,
  END_PROTECTION,
  LIKES,
  PACKAGE,
  PHONE,
  POLIS_ID,
  PROFILE,
  RECEIPT,
  TAG
} from '../../../../constants/icons'

const PolicyStatusBlock = ({ detailsData, isAgency, mobileTitle }) => {
  const { coverageEndDate, daysLeft } = getCoverageMeta(detailsData, isAgency)

  return (
    <>
      <h3 className='text-bold'>
        <IntlMessages id={mobileTitle ? 'Status Polis' : 'Status'} />
      </h3>
      {isAgency
        ? (
          daysLeft < 0 || detailsData.ExpiresAtObject?.CustomStatus === 'EXPIRED'
            ? (
              <div className='policy-status-alert-expired'>
                <p><IntlMessages id='Status Polis' /></p>
                <p>Telah Kadaluarsa Per : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
              </div>
            )
            : daysLeft <= 7
              ? (
                <div className='policy-status-alert-soon'>
                  <p><IntlMessages id='Status' /></p>
                  <p><IntlMessages id='Akan Berakhir Pada' /> : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
                </div>
              )
              : (
                <div className='policy-status-alert-active'>
                  <p><IntlMessages id='Status' /></p>
                  <p><IntlMessages id='Aktif Hingga' /> : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
                </div>
              )
        )
        : (
          daysLeft < 0
            ? (
              <div className='policy-status-alert-expired'>
                <p><IntlMessages id='Status Polis' /></p>
                <p>Telah Kadaluarsa Per : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
              </div>
            )
            : daysLeft <= 7 && detailsData.policy_coverage_status === 'active'
              ? (
                <div className='policy-status-alert-soon'>
                  <p><IntlMessages id='Status' /></p>
                  <p><IntlMessages id='Akan Berakhir Pada' /> : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
                </div>
              )
              : detailsData.policy_coverage_status === 'active'
                ? (
                  <div className='policy-status-alert-active'>
                    <p><IntlMessages id='Status' /></p>
                    <p><IntlMessages id='Aktif Hingga' /> : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
                  </div>
                )
                : (
                  <div className='policy-status-alert-expired'>
                    <p><IntlMessages id='Status Polis' /></p>
                    <p>Telah Kadaluarsa Per : {moment.utc(coverageEndDate).format('DD/MM/YYYY, h:mmA')}</p>
                  </div>
                )
        )}
    </>
  )
}

const PolicyDetailInfoSections = ({ detailsData, isAgency, layout }) => {
  const isMobile = layout === 'mobile'
  const holderTitle = isMobile ? 'Detail Pemegang Polis' : 'Data Pemegang Polis'

  return (
    <div className='policy-status-container'>
      <PolicyStatusBlock
        detailsData={detailsData}
        isAgency={isAgency}
        mobileTitle={isMobile}
      />
      <div className='policy-detail-card-container'>
        <h4 className='text-bold'><IntlMessages id={holderTitle} /></h4>
        <div className='policy-owner-items'>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={PROFILE} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Nama Lengkap' /></h1>
              <h1 className='text-bold'>{isAgency ? detailsData.Name : detailsData.CustomerName}</h1>
            </div>
          </div>
          {!isAgency ? (
            <div className='policy-detail-header-package-item'>
              <div className='logo-box'>
                <img src={PHONE} alt='' />
              </div>
              <div className='policy-detail-header-package-item-description'>
                <h1 className='text-sm-light'><IntlMessages id='Nomor Telepon' /></h1>
                <h1 className='text-bold'>{isMobile ? `+${detailsData.MobileNo}` : `${detailsData.MobileNo}`}</h1>
              </div>
            </div>
          ) : null}
        </div>
      </div>
      <div className='policy-detail-card-container'>
        <h4 className='text-bold'><IntlMessages id='Detail Asuransi' /></h4>
        <div className='insurance-detail-items'>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={CART} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Produk' /></h1>
              <h1 className='text-bold'>{isAgency ? detailsData.Category.Name : <IntlMessages id={detailsData.DisplayName} />}</h1>
            </div>
          </div>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={PACKAGE} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Paket' /></h1>
              <h1 className='text-bold'>{isAgency ? detailsData.Benefits[0] : <IntlMessages id={detailsData.PackageName} />}</h1>
            </div>
          </div>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={POLIS_ID} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='ID Polis' /></h1>
              <h1 className='text-bold'>{isAgency ? detailsData.InsurancePolicyNo : getPolicyId(detailsData, false)}</h1>
            </div>
          </div>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={TAG} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Kategori' /></h1>
              <h1 className='text-bold'><IntlMessages id={`${detailsData.Category.Name}`} /></h1>
            </div>
          </div>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={LIKES} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Partner' /></h1>
              <h1 className='text-bold'>{isAgency ? 'ppagency' : detailsData.PartnerName}</h1>
            </div>
          </div>
          <div className='policy-detail-header-package-item'>
            <div className='logo-box'>
              <img src={RECEIPT} alt='' />
            </div>
            <div className='policy-detail-header-package-item-description'>
              <h1 className='text-sm-light'><IntlMessages id='Jumlah Premi' /></h1>
              <h1 className='text-bold'>
                <NumberFormat
                  value={detailsData.Payments[0].Amount}
                  thousandSeparator='.'
                  decimalSeparator=','
                  displayType='text'
                />
              </h1>
            </div>
          </div>
        </div>
        <div className='policy-detail-card-container'>
          <h4 className='text-bold'><IntlMessages id='Protection Detail' /></h4>
          <div className='protection-detail'>
            <div className='policy-detail-header-package-item'>
              <div className='logo-box'>
                <img src={CALENDAR} alt='' />
              </div>
              <div className='policy-detail-header-package-item-description'>
                <h1 className='text-sm-light'><IntlMessages id='Tanggal Mulai Masa Perlindungan' /></h1>
                <h1 className='text-bold'>{moment.utc(detailsData.Payments[0].CoverageStartDate).format('DD/MM/YYYY, h:mmA')}</h1>
              </div>
            </div>
            <div className='policy-detail-header-package-item'>
              <div className='logo-box'>
                <img src={END_PROTECTION} alt='' />
              </div>
              <div className='policy-detail-header-package-item-description'>
                <h1 className='text-sm-light'><IntlMessages id='Tanggal Akhir Masa Perlindungan' /></h1>
                <h1 className='text-bold'>{moment.utc(detailsData.Payments[0].CoverageEndDate).format('DD/MM/YYYY, h:mmA')}</h1>
              </div>
            </div>
            <div className='policy-detail-header-package-item'>
              <div className='logo-box'>
                <img src={CLOCK} alt='' />
              </div>
              <div className='policy-detail-header-package-item-description'>
                <h1 className='text-sm-light'><IntlMessages id='Periode Perlindungan' /></h1>
                <h1 className='text-bold'>
                  {calculateDuration(detailsData.Payments[0].CoverageStartDate, detailsData.Payments[0].CoverageEndDate)}
                  {' '}
                  <IntlMessages id='Hari' />
                </h1>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default PolicyDetailInfoSections
