import { useCallback } from 'react'
import IntlMessages from '../../../../components/utility/intlMessages'

const PolicyDetailMobileTabs = ({ activeTab, isTabFixed, onTabChange }) => {
  const handlePolisDetailTabClick = useCallback(() => {
    onTabChange('Polis Detail')
  }, [onTabChange])

  const handleBenefitsTabClick = useCallback(() => {
    onTabChange('Daftar Benefit')
  }, [onTabChange])

  return (
    <div className={`policy-tab ${isTabFixed ? 'fixed' : ''}`}>
      <button
        type='button'
        className={activeTab === 'Polis Detail' ? 'active' : ''}
        onClick={handlePolisDetailTabClick}
      >
        <IntlMessages id='Policy Detail' />
      </button>
      <button
        type='button'
        className={activeTab === 'Daftar Benefit' ? 'active' : ''}
        onClick={handleBenefitsTabClick}
      >
        <IntlMessages id='Manfaat' />
      </button>
    </div>
  )
}

export default PolicyDetailMobileTabs
