import { useCallback, useEffect, useRef, useState } from 'react'
import { message } from 'antd'
import { useGeneratePolicyDocumentMutation } from '../../../request/query/policy/documentGeneration'

const DOCUMENT_NOT_READY_MESSAGE = 'Dokumen polis belum tersedia, silakan coba lagi'
const PARTNER_MISSING_MESSAGE = 'Partner tidak ditemukan, tidak dapat membuat dokumen polis'
export const POLICY_DOCUMENT_POLL_INTERVAL_MS = 2000
export const POLICY_DOCUMENT_POLL_MAX_ATTEMPTS = 15

export const DOWNLOAD_STATES = {
  DISABLED: 'disabled',
  GENERATING: 'generating',
  READY: 'ready',
  GENERATE: 'generate'
}

export const hasValidPolicyDocumentUrl = (url) => !!(url && url !== 'NA')

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

export const pollForPolicyDocumentUrl = async (
  onRefetchPolicyDetail,
  {
    intervalMs = POLICY_DOCUMENT_POLL_INTERVAL_MS,
    maxAttempts = POLICY_DOCUMENT_POLL_MAX_ATTEMPTS,
    shouldCancel = () => false
  } = {}
) => {
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    if (shouldCancel()) {
      return null
    }

    const detail = await onRefetchPolicyDetail()
    if (hasValidPolicyDocumentUrl(detail?.DocumentURL)) {
      return detail
    }

    if (attempt < maxAttempts - 1) {
      await sleep(intervalMs)
    }
  }

  return null
}

const getPartnerFromDetail = (detail = {}) => detail.Partner || detail.PartnerName || ''

export const isGojekPartner = (partner) =>
  String(partner || '').trim().toLowerCase() === 'gojek'

export const resolveDownloadState = ({ isAgency, userCanView, documentUrl, partner }) => {
  if (isAgency) {
    return hasValidPolicyDocumentUrl(documentUrl)
      ? DOWNLOAD_STATES.READY
      : DOWNLOAD_STATES.DISABLED
  }
  if (!userCanView) {
    return DOWNLOAD_STATES.DISABLED
  }
  if (hasValidPolicyDocumentUrl(documentUrl)) {
    return DOWNLOAD_STATES.READY
  }
  if (!isGojekPartner(partner)) {
    return DOWNLOAD_STATES.DISABLED
  }
  return DOWNLOAD_STATES.GENERATE
}

export const usePolicyDocumentDownload = ({
  detailsData = {},
  isAgency,
  onRefetchPolicyDetail
}) => {
  const documentUrl = detailsData.DocumentURL
  const userCanView = isAgency ? true : detailsData.UserViewDocumentURL
  const internalId = detailsData.InternalID
  const partner = getPartnerFromDetail(detailsData)

  const generateMutation = useGeneratePolicyDocumentMutation()
  const cancelledRef = useRef(false)
  const busyRef = useRef(false)
  const [isBusy, setIsBusy] = useState(false)

  const baseState = resolveDownloadState({ isAgency, userCanView, documentUrl, partner })
  const downloadState = isBusy ? DOWNLOAD_STATES.GENERATING : baseState

  const onGenerate = useCallback(async () => {
    if (cancelledRef.current || busyRef.current) {
      return
    }

    busyRef.current = true
    setIsBusy(true)

    try {
      const freshDetail = await onRefetchPolicyDetail()
      const resolvedInternalId = freshDetail?.InternalID || internalId
      const resolvedPartner = getPartnerFromDetail(freshDetail) || partner

      if (hasValidPolicyDocumentUrl(freshDetail?.DocumentURL)) {
        return
      }

      if (!resolvedInternalId || !resolvedPartner) {
        message.error(PARTNER_MISSING_MESSAGE)
        return
      }

      if (!isGojekPartner(resolvedPartner)) {
        return
      }

      await generateMutation.mutateAsync({
        internalId: resolvedInternalId,
        partner: resolvedPartner
      })

      const readyDetail = await pollForPolicyDocumentUrl(onRefetchPolicyDetail, {
        shouldCancel: () => cancelledRef.current
      })

      if (cancelledRef.current) {
        return
      }

      if (!readyDetail) {
        message.error(DOCUMENT_NOT_READY_MESSAGE)
      }
    } catch (err) {
      if (cancelledRef.current) {
        return
      }
      message.error(err?.message || DOCUMENT_NOT_READY_MESSAGE)
    } finally {
      busyRef.current = false
      if (!cancelledRef.current) {
        setIsBusy(false)
      }
    }
  }, [generateMutation, internalId, onRefetchPolicyDetail, partner])

  useEffect(() => {
    cancelledRef.current = false

    return () => {
      cancelledRef.current = true
    }
  }, [internalId])

  return {
    documentUrl,
    downloadState,
    onGenerate,
    isDownloadDocument: userCanView
  }
}
