import { useCallback } from 'react'
import { Button, Alert, Row, Col } from 'antd'
import { useHistory } from 'react-router-dom'
import IntlMessages from '../../../../components/utility/intlMessages'

const PolicyDetailError = ({ message }) => {
  const history = useHistory()

  const handleBack = useCallback(() => {
    history.push('/')
  }, [history])

  return (
    <div>
      <Row className='policy-list' style={{ marginTop: '70px' }}>
        <Col xl={12} lg={12} offset={6}>
          <Row style={{ marginBottom: '20px' }}>
            <Col xl={24} lg={24}>
              <Alert
                style={{ marginTop: '10px' }}
                message=''
                description={<IntlMessages id={message} />}
                type='error'
                showIcon
                closable
              />
              <div style={{ float: 'right', marginTop: '20px' }}>
                <Button onClick={handleBack}><IntlMessages id='Kembali' /></Button>
              </div>
            </Col>
          </Row>
        </Col>
      </Row>
    </div>
  )
}

export default PolicyDetailError
