import React, { Component } from 'react'
import PropTypes from 'prop-types'
import IntlMessages from '../../../../components/utility/intlMessages'
import { Button } from 'antd'

class PolicyDetailBtn extends Component {
  static propTypes = {
    onCreateClaim: PropTypes.func,
    documentUrl: PropTypes.string,
    isDownloadDocument: PropTypes.bool,
    downloadState: PropTypes.oneOf(['disabled', 'generating', 'ready', 'generate']),
    onGenerate: PropTypes.func
  }

  renderDownloadButton () {
    const {
      documentUrl,
      isDownloadDocument,
      downloadState,
      onGenerate
    } = this.props

    const resolvedState = downloadState || (
      !isDownloadDocument || !documentUrl || documentUrl === 'NA'
        ? 'disabled'
        : 'ready'
    )

    if (resolvedState === 'generating') {
      return (
        <Button className='download-details' loading disabled>
          <IntlMessages id='Buat Sertifikat' />
        </Button>
      )
    }

    if (resolvedState === 'generate') {
      return (
        <Button className='download-details' onClick={onGenerate}>
          <IntlMessages id='Buat Sertifikat' />
        </Button>
      )
    }

    if (resolvedState === 'ready') {
      return (
        <a href={documentUrl} target='_blank' rel='noopener noreferrer' className='no-style'>
          <Button className='download-details'>
            <IntlMessages id='Unduh Sertifikat Polis' />
          </Button>
        </a>
      )
    }

    return (
      <Button className='download-details' disabled>
        <IntlMessages id='Unduh Sertifikat Polis' />
      </Button>
    )
  }

  render () {
    const { onCreateClaim, policyBtnContainerStyle } = this.props

    return (
      <React.Fragment>
        <div className={`${policyBtnContainerStyle}`}>
          <Button
            className='initiate-claim-button'
            onClick={onCreateClaim}
          >
            <IntlMessages id='Buat Klaim' />
          </Button>
          {this.renderDownloadButton()}
        </div>
      </React.Fragment>
    )
  }
}

export default PolicyDetailBtn
