import { useCallback, useEffect, useMemo, useState } from 'react'
import { Icon } from 'antd'
import { connect } from 'react-redux'
import { useIntl } from 'react-intl'
import { useQueryClient } from '@tanstack/react-query'
import { PolicyDetailContainer, PolicyStyleWrapper } from '../policyDetails/index.style'
import { sanitizeAgencyPolicyDetail, sanitizeB2cPolicyDetail } from '../../../helpers/utility'
import IntlMessages from '../../../components/utility/intlMessages'
import BenefitList from '../../BenefitList'
import claimActions from '../../../redux/claim/actions'
import { usePolicyDetailQuery, POLICY_DETAIL_KEY } from '../../../request/query/policy'
import { useBenefitsListQuery } from '../../../request/query/claim/benefits'
import { getPartnerFromDetail } from './policyDetailHelpers'
import { usePolicyDetailParams } from './hooks/usePolicyDetailParams'
import { usePolicyDetailScroll } from './hooks/usePolicyDetailScroll'
import PolicyDetailPageHeader from './components/PolicyDetailPageHeader'
import PolicyDetailMobileTabs from './components/PolicyDetailMobileTabs'
import PolicyDetailInfoSections from './components/PolicyDetailInfoSections'
import PolicyBenefitsAccordion from './components/PolicyBenefitsAccordion'
import PolicyDetailError from './components/PolicyDetailError'

const { resetReduxState } = claimActions

const PolicyDetails = ({ match, location, history, isDanaUser, resetReduxState: resetClaimState }) => {
  const intl = useIntl()
  const queryClient = useQueryClient()
  const policyId = match.params.id

  const { isAgency, isSSOSession } = usePolicyDetailParams(location)
  const { isTabFixed, isNarrowMobile } = usePolicyDetailScroll()

  const [showModal, setShowModal] = useState(false)
  const [showClaimInit, setShowClaimInit] = useState(true)
  const [activeTab, setActiveTab] = useState('Polis Detail')
  const [packageNameInfo, setPackageNameInfo] = useState(null)

  const {
    data: policyData,
    isLoading,
    isError,
    error,
    refetch: refetchPolicyDetail
  } = usePolicyDetailQuery({
    policyId,
    isAgency,
    isSSO: isSSOSession
  })

  const detailsData = policyData?.detailsData || {}
  const resolvedIsAgency = policyData?.isAgency ?? isAgency

  const packageCode = resolvedIsAgency
    ? detailsData.PackageCodeSlug || detailsData.PackageCode
    : detailsData.PackageCodeSlug
  const productKey = detailsData.ProductKey
  const partner = getPartnerFromDetail(detailsData)
  const insuranceProvider = detailsData.InsuranceProvider

  const {
    data: benefitsData
  } = useBenefitsListQuery({
    packageCode,
    product: productKey,
    partner,
    insuranceProvider,
    isAgency: resolvedIsAgency,
    enabled: resolvedIsAgency
      ? !!(packageCode && productKey)
      : !!(packageCode && productKey && partner)
  })

  const benefitQueryParams = useMemo(() => {
    const sanitized = resolvedIsAgency
      ? sanitizeAgencyPolicyDetail(detailsData, intl)
      : sanitizeB2cPolicyDetail(detailsData, intl)

    return {
      ...sanitized,
      partner: partner || sanitized.partner
    }
  }, [detailsData, resolvedIsAgency, intl, partner])

  useEffect(() => {
    return () => {
      queryClient.removeQueries({ queryKey: [POLICY_DETAIL_KEY, policyId] })
    }
  }, [policyId, queryClient])

  useEffect(() => {
    if (
      !isLoading &&
      detailsData &&
      Object.keys(detailsData).length &&
      showClaimInit &&
      isDanaUser &&
      history.action === 'POP'
    ) {
      setShowClaimInit(false)
    }
  }, [isLoading, detailsData, showClaimInit, isDanaUser, history])

  const handleCancelShowBenefits = useCallback(() => {
    setShowModal(false)
    resetClaimState()
  }, [resetClaimState])

  const handleCreateClaim = useCallback(() => {
    const packageCodeSlug = resolvedIsAgency
      ? detailsData.PackageCodeSlug || detailsData.PackageCode
      : detailsData.PackageCodeSlug

    if (!packageCodeSlug) {
      setPackageNameInfo(
        <IntlMessages id='Maaf, anda tidak bisa melakukan klaim. Paket anda tidak ada' />
      )
      return
    }
    setShowModal(true)
  }, [detailsData, resolvedIsAgency])

  const handleTabChange = useCallback((tab) => {
    setActiveTab(tab)
  }, [])

  const handleRefetchPolicyDetail = useCallback(async () => {
    const result = await refetchPolicyDetail()
    return result.data?.detailsData || {}
  }, [refetchPolicyDetail])

  const errorMessage = isError
    ? (error?.message || 'Gagal untuk mengambil detail policy')
    : null

  const benefitsList = benefitsData?.benefitList || []

  const renderContent = () => {
    if (isLoading) {
      return (
        <center>
          <Icon type='loading' className='loader' style={{ marginTop: '100px' }} />
        </center>
      )
    }

    if (errorMessage) {
      return <PolicyDetailError message={errorMessage} />
    }

    if (!detailsData || !Object.keys(detailsData).length) {
      return null
    }

    return (
      <div>
        <PolicyDetailPageHeader
          detailsData={detailsData}
          isAgency={resolvedIsAgency}
          onCreateClaim={handleCreateClaim}
          onRefetchPolicyDetail={handleRefetchPolicyDetail}
        />
        {isNarrowMobile ? (
          <PolicyDetailMobileTabs
            activeTab={activeTab}
            isTabFixed={isTabFixed}
            onTabChange={handleTabChange}
          />
        ) : null}
        {isNarrowMobile && activeTab === 'Polis Detail' ? (
          <PolicyDetailContainer>
            <div className='policy-detail-card'>
              <PolicyDetailInfoSections
                detailsData={detailsData}
                isAgency={resolvedIsAgency}
                layout='mobile'
              />
            </div>
          </PolicyDetailContainer>
        ) : null}
        {isNarrowMobile && activeTab === 'Daftar Benefit' ? (
          <PolicyDetailContainer>
            <PolicyBenefitsAccordion
              detailsData={detailsData}
              isAgency={resolvedIsAgency}
              benefitsList={benefitsList}
              showTitle={false}
            />
          </PolicyDetailContainer>
        ) : null}
        {!isNarrowMobile ? (
          <>
            <PolicyDetailContainer>
              <div className='policy-detail-card'>
                <h1 className='text-big-bold'><IntlMessages id='Policy Detail' /></h1>
                <PolicyDetailInfoSections
                  detailsData={detailsData}
                  isAgency={resolvedIsAgency}
                  layout='desktop'
                />
              </div>
            </PolicyDetailContainer>
            <PolicyDetailContainer>
              <PolicyBenefitsAccordion
                detailsData={detailsData}
                isAgency={resolvedIsAgency}
                benefitsList={benefitsList}
                showTitle
              />
            </PolicyDetailContainer>
          </>
        ) : null}
        {packageNameInfo}
      </div>
    )
  }

  if (isDanaUser) {
    return (
      <PolicyStyleWrapper>
        {showModal ? (
          <BenefitList
            isAgency={resolvedIsAgency}
            closeBenefitModalPolicyList={handleCancelShowBenefits}
            benefitQueryParams={benefitQueryParams}
          />
        ) : null}
      </PolicyStyleWrapper>
    )
  }

  return (
    <PolicyStyleWrapper>
      {showModal ? (
        <BenefitList
          isAgency={resolvedIsAgency}
          closeBenefitModalPolicyList={handleCancelShowBenefits}
          benefitQueryParams={benefitQueryParams}
        />
      ) : null}
      <div>{renderContent()}</div>
    </PolicyStyleWrapper>
  )
}

export default connect(
  (state) => ({ isDanaUser: state.User.isDanaUser }),
  { resetReduxState }
)(PolicyDetails)
