import { useQuery } from '@tanstack/react-query'
import policyApi from '../../axios/policy'
import agencyApi from '../../axios/agency'
import { policyDetailMapping } from '../../../helpers/agencyUtils'
import { assertApiOk } from '../assertApiOk'

export const POLICY_DETAIL_KEY = 'policy-detail'

const fetchB2cPolicyDetail = async (policyId) => {
  const res = await policyApi.getPolicyDetails({ payload: policyId })
  return assertApiOk(res)
}

const fetchAgencyPolicyDetail = async (policyId) => {
  const res = await agencyApi.getAgentPolicyDetails({ payload: policyId })
  const data = typeof res.data === 'string' ? JSON.parse(res.data) : res.data
  return assertApiOk({ ...res, data })
}

export const usePolicyDetailQuery = ({ policyId, isAgency, isSSO, enabled = true }) => {
  const useAgencyApi = isAgency || isSSO

  return useQuery({
    queryKey: [POLICY_DETAIL_KEY, policyId, useAgencyApi ? 'agency' : 'b2c'],
    queryFn: () => (useAgencyApi
      ? fetchAgencyPolicyDetail(policyId)
      : fetchB2cPolicyDetail(policyId)),
    enabled: enabled && !!policyId,
    select: (raw) => {
      if (useAgencyApi) {
        return {
          detailsData: policyDetailMapping(raw),
          rawData: raw,
          isAgency: true
        }
      }
      return {
        detailsData: raw,
        rawData: raw,
        isAgency: false
      }
    }
  })
}
