import { useMemo } from 'react'
import isSSO from '../../../../helpers/isSSOSession'

export const usePolicyDetailParams = (location) => {
  return useMemo(() => {
    const params = new URLSearchParams(location.search)
    let source = params.get('source')
    let isAgency

    if (params.has('isAgency')) {
      isAgency = params.get('isAgency') === 'true'
    }

    if (location?.state) {
      source = location.state.source || source
      if (location.state.isAgency !== undefined) {
        isAgency = location.state.isAgency
      }
    }

    const isSSOSession = isSSO()

    return {
      source,
      isAgency: !!(isAgency || isSSOSession),
      isSSOSession
    }
  }, [location.search, location.state])
}
