import { ARROW_DOWN, ARROW_UP } from '../../constants/icons'
import { AccordionItemContainer } from './Accordion.style'
import IntlMessages from '../utility/intlMessages'

export const AccordionItem = ({ title, content, isOpen, onClick, isAgency }) => {
  return (
    <AccordionItemContainer>
      <button onClick={isAgency ? null : onClick} className='accordion-button'>
        <div className='accordion-title'>
          <p>
            <IntlMessages id={title} />
          </p>
          {
            !isAgency && (
              isOpen
                ? <img src={ARROW_UP} />
                : <img src={ARROW_DOWN} width={18} />
            )
          }
        </div>
      </button>
      {isOpen && (
        <div className='accordion-content'>
          <IntlMessages id={content} />
        </div>
      )}
    </AccordionItemContainer>
  )
}
