import { useMutation } from '@tanstack/react-query'
import policyApi from '../../axios/policy'
import { assertApiOk } from '../assertApiOk'

export const GENERATE_POLICY_DOCUMENT_KEY = 'generate-policy-document'

export const useGeneratePolicyDocumentMutation = () =>
  useMutation({
    mutationKey: [GENERATE_POLICY_DOCUMENT_KEY],
    mutationFn: async ({ internalId, partner }) => {
      const res = await policyApi.postEndorseConfigPolicy({ internalId, partner })
      return assertApiOk(res, [200, 201])
    }
  })
