import PropTypes from 'prop-types'
import PolicyDetailBtn from './PolicyDetailBtn'
import { usePolicyDocumentDownload } from '../hooks/usePolicyDocumentDownload'

const PolicyDetailDownloadSection = ({
  detailsData,
  isAgency,
  onCreateClaim,
  onRefetchPolicyDetail,
  policyBtnContainerStyle
}) => {
  const {
    documentUrl,
    downloadState,
    onGenerate,
    isDownloadDocument
  } = usePolicyDocumentDownload({
    detailsData,
    isAgency,
    onRefetchPolicyDetail
  })

  return (
    <PolicyDetailBtn
      documentUrl={documentUrl}
      onCreateClaim={onCreateClaim}
      isDownloadDocument={isDownloadDocument}
      downloadState={downloadState}
      onGenerate={onGenerate}
      policyBtnContainerStyle={policyBtnContainerStyle}
    />
  )
}

PolicyDetailDownloadSection.propTypes = {
  detailsData: PropTypes.object,
  isAgency: PropTypes.bool,
  onCreateClaim: PropTypes.func,
  onRefetchPolicyDetail: PropTypes.func.isRequired,
  policyBtnContainerStyle: PropTypes.string
}

export default PolicyDetailDownloadSection
