import { useCallback, useEffect, useState } from 'react'

const NARROW_MOBILE_MAX = 430

export const usePolicyDetailScroll = () => {
  const [isTabFixed, setIsTabFixed] = useState(false)
  const [isNarrowMobile, setIsNarrowMobile] = useState(
    typeof window !== 'undefined' ? window.innerWidth <= NARROW_MOBILE_MAX : false
  )

  const handleScroll = useCallback(() => {
    const policyDetailHeader = document.querySelector('.policy-detail-header-content')
    if (!policyDetailHeader) {
      return
    }
    const isFixed = policyDetailHeader.getBoundingClientRect().bottom <= 0
    setIsTabFixed((prev) => (prev !== isFixed ? isFixed : prev))
  }, [])

  const handleResize = useCallback(() => {
    setIsNarrowMobile(window.innerWidth <= NARROW_MOBILE_MAX)
  }, [])

  useEffect(() => {
    window.addEventListener('scroll', handleScroll)
    window.addEventListener('resize', handleResize)
    return () => {
      window.removeEventListener('scroll', handleScroll)
      window.removeEventListener('resize', handleResize)
    }
  }, [handleScroll, handleResize])

  return { isTabFixed, isNarrowMobile }
}
