import moment from 'moment'

export const calculateDuration = (startDate, endDate) => {
  const start = new Date(startDate)
  const end = new Date(endDate)
  const MS_PER_DAY = 1000 * 60 * 60 * 24;
  const differenceInMilliseconds = end - start
  const differenceInDays = differenceInMilliseconds / MS_PER_DAY

   return Math.floor(differenceInDays)
}

export const getBenefitsMap = (benefitsList) => {
  if (!benefitsList?.length) {
    return []
  }

  return benefitsList.flatMap((item) =>
    (item?.benefits || []).map((benefit) => ({
      benefitName: benefit.benefit_name || '',
      description: benefit.description || '',
      amount: ''
    }))
  )
}

export const getCoverageMeta = (detailsData, isAgency) => {
  const now = moment().utc().format('YYYY-MM-DDTHH:mm:ss[Z]')
  const coverageEndDate = detailsData.Payments?.[0]?.CoverageEndDate
  const daysLeft = coverageEndDate ? calculateDuration(now, coverageEndDate) : null
  return { coverageEndDate, daysLeft }
}

export const getPartnerFromDetail = (detailsData) =>
  detailsData.Partner || detailsData.PartnerName || ''
