import IntlMessages from '../../../../components/utility/intlMessages'
import { Accordion } from '../../../../components/Accordion/Accordion'
import { getBenefitsMap } from '../policyDetailHelpers'

const PolicyBenefitsAccordion = ({ detailsData, isAgency, benefitsList, showTitle }) => {
  const items = isAgency ? detailsData.Benefits : getBenefitsMap(benefitsList)

  return (
    <div className='policy-detail-card'>
      {showTitle ? <h1 className='text-big-bold'><IntlMessages id='Manfaat' /></h1> : null}
      <Accordion
        items={items}
        titleKey='benefitName'
        contentKey='description'
        isAgency={isAgency}
      />
    </div>
  )
}

export default PolicyBenefitsAccordion
